# Harvey L. Carter, « Tom Tobin », The American West, vol. II, n° 4 (automne 1965), p. 91-94 (avec la recension de Ray Allen
# Billington, « Mountain Men — A Review and a Tribute », p. 90-91). PDF du Drive de l'auteur (HISTOIRE_LIVRES/FAR_WEST, v2n4.pdf),
# lu en entier dans la visionneuse du Drive. Corpus « Recherches », préfixe CT65.
# Tom Tobin, demi-frère de Charles Autobees (fils de François Autobees, ou Ortubise), porta le nom d'Autobees jusqu'en 1853.
from commun import Corpus
CT = "Carter, Harvey L. (1965), « Tom Tobin », The American West, vol. II, n° 4, p. 91-94"
C = Corpus('Recherches', 'CT65', CT, page_fmt='p. {}')
F = C.F
F('01', "Arroyo Hondo : « Tom Autobees », demi-frère de Charles Autobees, épouse Pascuala Bernal sous le nom d'Ortibi (1837-1844)", 'famille', '1837/1844-11-03', -105.665, 36.537, 'c', ['Tom Tobin', 'Charles Autobees', 'François Autobees', 'Sarah Tishman', 'Pascuala Bernal', 'Simeon Turley'],
  "Né à Saint-Louis vers 1823 de Bartholomew Tobin, journalier irlandais, et de Sarah Tishman, qui avait eu de François Autobees (Francisco Ortibi) le trappeur Charles Autobees, Tom Tobin rejoint en 1837 son demi-frère à Taos. Il prend le nom d'Autobees, vit chez Charles, travaille pour Simeon Turley et le suit au fort Lupton en 1841 et 1842. Le 3 novembre 1844, à vingt et un ans, il épouse à Taos Pascuala Bernal, d'Arroyo Hondo, où se trouvent le moulin et la distillerie de Turley ; il se dit alors fils de « Bartolome Ortibi » et de « Serafina Tishman », adaptant le nom de son père à celui qu'il porte.", '91-92, 94', "Registres matrimoniaux de Taos (1833-1845), p. 272, cités par Carter d'après Fray Angélico Chávez et Janet Lecompte.")
F('02', "Santa Fe et la Taos Trail : Tom Autobees dans la compagnie de St. Vrain, puis peut-être le « Tom » de Garrard (1847)", 'evenement', '1847-01-20/1847-03', -105.938, 35.687, 'a', ['Tom Tobin', 'Charles Autobees', 'Ceran St. Vrain', 'William LeBlanc', 'Lucien Maxwell', 'Manuel Lefèvre', 'Basile Lajeunesse', 'Lewis H. Garrard'],
  "Pendant la révolte de Taos, Tom se trouve au moulin de Turley : le 20 janvier 1847, avec William LeBlanc et Turley, il perce un mur d'adobe et s'enfuit ; LeBlanc gagne le Greenhorn, Tom descend à Santa Fe, où il s'enrôle avec Charles dans la compagnie de volontaires de Ceran St. Vrain (« Charles et Thomas Antibes » sur la liste de Prince), licenciée le 20 février. Carter l'identifie au trappeur libre « Tom » qui accompagne, avec Lucien Maxwell, Manuel Lefèvre et Basile Lajeunesse, le convoi de Bent et St. Vrain décrit par Garrard ; Tobin dira avoir porté le rapport de Kearny de Santa Fe au fort Leavenworth en moins de onze jours.", '92, 94', "Identification proposée par Carter.")
F('03', "Rio Colorado (Questa) : Heap engage « Thomas Otterby » sur la recommandation de Charles Autobees (6 juillet 1853)", 'exploration', '1853-07-06', -105.595, 36.704, 'c', ['Tom Tobin', 'Charles Autobees', 'Gwinn Harris Heap', 'Edward F. Beale'],
  "Ayant perdu ses bagages au gué de la Gunnison, l'expédition Beale envoie Gwinn Harris Heap chercher des vivres à Taos. Le 6 juillet 1853, Heap loge chez Charles Autobees, installé depuis 1850 à la colonie du Rio Colorado, et engage sur sa recommandation « un jeune Américain, Thomas Otterby », réputé presque l'égal de Kit Carson, comme éclaireur et guide jusqu'en Californie. C'est à son retour qu'il abandonne le nom d'Autobees pour reprendre celui de Tobin.", '92', "Heap, Central Route to the Pacific (éd. Hafen 1957), p. 178, cité par Carter.")
F('04', "Fort Garland : Tom Tobin, les Espinosa et la fin d'un homme des montagnes (1863-1904)", 'personnage', '1858~/1904-05-16', -105.430, 37.425, 'c', ['Tom Tobin', 'Pascuala Bernal', 'William Carson', 'Rosa Quintana', 'Samuel Tappan'],
  "Établi à la fin des années 1850 sur un quart de section à six milles à l'ouest du fort Garland, Tobin traque en septembre 1863, à la demande du colonel Tappan, les bandits Espinosa et rapporte leurs têtes au fort le 11. Sa fille Pascualita épouse William Carson, fils aîné de Kit Carson, qui le blesse un jour d'un coup de feu ; veuf de Pascuala Bernal en 1887, il se remarie avec Rosa Quintana et meurt presque aveugle et sans ressources le 16 mai 1904. Son fusil, gravé « St. Louis », a été donné en 1958 à l'Abbey School.", '92-94')
fiches = C.fiches
